-- ÁPICE IMÓVEIS — ATUALIZA O CATÁLOGO PARA OS 20 IMÓVEIS DA PLANILHA (Apice_Imoveis_Dados_dos_Imoveis.xlsx)
-- Supabase > SQL Editor > New query > cole TUDO > Run. Rode DEPOIS do supabase-tudo.sql. Pode rodar de novo sem problema.
-- Imóveis 4, 18, 19 e 20 entram como 'oculto' (sem fotos); mais 3 imóveis antigos ficam 'oculto'. Para publicar: Acesso restrito > status Ativo.
begin;
alter table imoveis add column if not exists detalhes jsonb default '{}'::jsonb;

-- 1) Remove os imóveis antigos importados do WhatsApp (ids aleatórios; reconhecidos pelas fotos 'imoveis/...').
--    Imóveis cadastrados pelo painel (fotos no Storage) NÃO são tocados.
delete from imoveis where fotos[1] like 'imoveis/%' and id not in ('a91ce000-0000-4000-8000-000000000001','a91ce000-0000-4000-8000-000000000002','a91ce000-0000-4000-8000-000000000003','a91ce000-0000-4000-8000-000000000004','a91ce000-0000-4000-8000-000000000005','a91ce000-0000-4000-8000-000000000006','a91ce000-0000-4000-8000-000000000007','a91ce000-0000-4000-8000-000000000008','a91ce000-0000-4000-8000-000000000009','a91ce000-0000-4000-8000-000000000010','a91ce000-0000-4000-8000-000000000011','a91ce000-0000-4000-8000-000000000012','a91ce000-0000-4000-8000-000000000013','a91ce000-0000-4000-8000-000000000014','a91ce000-0000-4000-8000-000000000015','a91ce000-0000-4000-8000-000000000016','a91ce000-0000-4000-8000-000000000017','a91ce000-0000-4000-8000-000000000018','a91ce000-0000-4000-8000-000000000019','a91ce000-0000-4000-8000-000000000020','a91ce000-0000-4000-8000-000000000021','a91ce000-0000-4000-8000-000000000022','a91ce000-0000-4000-8000-000000000023');

-- 2) Os 20 imóveis da planilha (ids fixos) + 3 antigos ocultos
on conflict (id) do update set categoria=excluded.categoria,tipo=excluded.tipo,titulo=excluded.titulo,cidade=excluded.cidade,preco=excluded.preco,area=excluded.area,quartos=excluded.quartos,suites=excluded.suites,vagas=excluded.vagas,descricao=excluded.descricao,fotos=excluded.fotos,videos=excluded.videos,destaque=excluded.destaque,status=excluded.status,detalhes=excluded.detalhes;
commit;
